const WISSEN_ALLGEMEIN = [
  { kat:"betrieb", t:"VRAM-Faustformel",
    txt:"Speicherbedarf ungefähr: Parameter mal Bit geteilt durch 8, plus rund 10 Prozent Aufschlag, plus Kontext-Cache. Ein 8B-Modell braucht in 16 Bit also etwa 17 bis 18 GB, in 4 Bit nur noch rund 4,5 GB plus Cache. Darum ist die Diät (Quantisierung) der Schlüssel zum Heimstall." },
  { kat:"betrieb", t:"Bandbreite bestimmt das Tempo",
    /* Ära 7.5 (Lehr-Audit #15): Einzelanfrage-Vorbehalt ergänzt – sonst Widerspruch zur Batching-Karte. */
    txt:"Beim Antworten muss die Karte für jedes Token fast alle Gewichte einmal aus dem Speicher lesen. Faustregel: Token pro Sekunde ungefähr Speicherbandbreite geteilt durch Modellgröße in GB. Eine RTX 4090 mit rund 1000 GB/s schafft mit einem 5-GB-Modell also grob 100 bis 200 Token pro Sekunde – Rechenleistung ist selten der Engpass. Wichtig: Das gilt für eine EINZELNE Anfrage ohne vorausschauendes Decoding. Im Batch teilen sich viele Anfragen denselben Gewichte-Lesevorgang – dann steigt der Gesamtdurchsatz des Servers, nicht das Tempo der einzelnen Antwort.",
    stand:"08/2026", quelle:"Herleitung aus der Speicherbandbreite; Kartenwerte laut Herstellerangaben" },
  { kat:"betrieb", t:"Needle 2 – ein Modell in 14 MB",
    txt:"Needle 2 von Cactus Compute hat 45 Millionen Parameter (hidden 512, 27 Schichten, Vokabular 8 192) und ist auf rund 2,2 Bit je Gewicht komprimiert – eine einzige 14-MB-Datei, die in 28 MB Arbeitsspeicher läuft: auf Handys, dem Raspberry Pi, in WebAssembly im Browser, sogar auf einem ESP32-Mikrocontroller. Es ist kein Chatmodell: Es kennt 256 Token Kontext, Werkzeugschemata werden fest eingeblendet, und die Ausgabe ist immer JSON. Lizenz Apache-2.0.",
    stand:"09/2026", quelle:"huggingface.co/Cactus-Compute/needle2; github.com/cactus-compute/needle" },
  { kat:"betrieb", t:"Werkzeugaufrufe: Text rein, JSON raus",
    txt:"Beim Werkzeugaufrufe bekommt ein Modell eine Liste von Werkzeugen mit Parameterschema und soll aus einem Satz den passenden Aufruf bauen – etwa aus „dim the kitchen to 10“ den Aufruf set_lights(room=kitchen, brightness=10). Needle 2 erzwingt gültiges JSON über eine Byte-Grammatik, wählt bei vielen Werkzeugen nur die fünf passendsten (Retrieval-Kopf) und liefert einen Konfidenzwert. Im Hofsprecher entscheidet trotzdem immer die Vorschau: Das Modell schlägt vor, der Hof rechnet und du bestätigst.",
    stand:"09/2026", quelle:"github.com/cactus-compute/needle (README); eigene Messung LLM FARM 02.09.2026" },
  { kat:"betrieb", t:"Warum 45 Millionen Parameter nicht plaudern können",
    txt:"Sprachwissen und Weltwissen stecken in Parametern: Ein 4-B-Modell trägt fast hundertmal mehr davon als die Nadel. Needle 2 wurde gezielt auf Werkzeugaufrufe trainiert – es hat keinen Textgenerierungs-Modus, kann nicht zusammenfassen, nichts erklären und kein Deutsch schreiben. Unsere Messung: Englische Hof-Befehle 24 von 25 richtig, deutsche 14 von 22; die Konfidenz war bei fachfremden Werkzeugen kein verlässlicher Wächter. Kleine Spezialisten sind billig und schnell – aber nur für genau ihre Aufgabe.",
    stand:"09/2026", quelle:"eigene Messung LLM FARM 02.09.2026 (cactus-needle 2.0.11, WebAssembly in Node 22)" },
  { kat:"betrieb", t:"Kleinstgeräte: Raspberry Pi, Handy, ESP32",
    txt:"Was ein Modell braucht, ist Speicher und Bandbreite. Ein Raspberry Pi 5 hat 8 GB gemeinsamen Speicher bei rund 17 GB/s – ein 4-B-Modell in Q4 (2,5 GB) käme dort auf wenige Token pro Sekunde, die 14-MB-Nadel laut Hersteller auf 500. Handys unter 200 Dollar schaffen 300 bis 700, ein ESP32-P4 mit 32 MB PSRAM trägt die Nadel gerade so. Im Spiel gibt es den Pi als Rechner für die Nadelklasse; Grafikkarten sind für sie überdimensioniert.",
    stand:"09/2026", quelle:"huggingface.co/Cactus-Compute/needle2 (Modellkarte); Raspberry Pi Foundation (Pi 5: LPDDR4X-4267, 8 GB)" },
  { kat:"betrieb", t:"Unified Memory: viel Platz, wenig Tempo",
    txt:"Mini-PCs mit Ryzen AI Max+ 395, NVIDIAs DGX Spark und Apples Mac Studio teilen einen großen Speicher (bis 128 GB, beim Mac bis 512 GB) zwischen CPU und GPU. Damit passen Modelle hinein, die auf keine Grafikkarte passen – aber die Bandbreite liegt bei 256 bis 546 GB/s statt 1000 bis 1800 GB/s. Folge: MoE-Modelle mit wenigen aktiven Parametern (gpt-oss-120b) laufen mit 35 bis 45 Token pro Sekunde, dichte 70B-Modelle nur mit 3 bis 5. Der Prefill (Einlesen langer Eingaben) ist ohne dicke GPU besonders langsam.",
    stand:"09/2026", quelle:"heise (10/2025): Lokale KI-Modelle sind jetzt brauchbar; AI mit Arnie: Hardware für lokale KI" },
  { kat:"betrieb", t:"NPU und iGPU: nicht für Sprachmodelle",
    txt:"Die NPUs in aktuellen Laptops (10 bis 50 TOPS) sind für kleine Bild- und Audio-Netze gedacht. Sprachmodelle brauchen Speicherbandbreite, nicht Marketing-TOPS: Auf NPU oder Laptop-iGPU laufen LLMs nicht nennenswert schneller als auf der CPU. Ein 16-Kern-Prozessor mit DDR5-5600 (90 GB/s) schafft bei einem 60-GB-Modell rund drei Token pro Sekunde – eine RTX 4090 mit 128 GB Arbeitsspeicher als Auslagerung immerhin 14.",
    stand:"09/2026", quelle:"heise (10/2025); AI mit Arnie: Hardware für lokale KI" },
  { kat:"betrieb", t:"NVLink, Multi-GPU und der Gebraucht-Geheimtipp",
    txt:"Mehrere Karten teilen sich ein Modell über PCIe – das geht, aber der Datenaustausch bremst. NVLink (schnelle Kartenbrücke) gibt es im Consumer-Bereich nur bis zur RTX 3090; die 4090 und 5090 haben keine. Deshalb gilt die gebrauchte 3090 (24 GB, rund 700 Euro) als Einsteiger-Geheimtipp: drei Stück ergeben 72 GB und fahren ein 120B-MoE-Modell mit über 50 Token pro Sekunde – bei deutlich mehr Stromverbrauch als eine Unified-Memory-Box.",
    stand:"09/2026", quelle:"heise (10/2025); AI mit Arnie: Hardware für lokale KI" },
  { kat:"betrieb", t:"Was lokale Modelle NICHT können",
    txt:"Ohne Werkzeuge (MCP, Suche) kennt ein lokales Modell nur seinen Trainingsstand – es kann nicht ins Netz. Kleine Modelle taugen nicht als Wissensdatenbank: sie halluzinieren und sind veraltet; Wissen gehört in RAG-Quellen, nicht ins Gewicht. Und mehrere 5090 lassen sich nicht per NVLink koppeln. Auf dem Hof heißt das: Wissenszettel brauchen die Wissenswerkstatt, Werkzeug-Zettel ein Agenten-Tool, und der Viehmarkt zeigt ehrlich Bandbreite statt TOPS.",
    stand:"09/2026", quelle:"heise (10/2025); AI mit Arnie: Hardware für lokale KI" },
  { kat:"betrieb", t:"Das MoE-Prinzip",
    txt:"Mixture-of-Experts-Modelle halten viele Experten im Speicher, rechnen pro Token aber nur mit wenigen. Kimi K2 hat rund 1000 Milliarden Parameter, aktiviert je Token aber nur etwa 32 Milliarden. Folge: Man braucht viel VRAM, bekommt dafür aber das Tempo eines viel kleineren Modells." },
  { kat:"betrieb", t:"Watt und Stromrechnung",
    txt:"Eine RTX 4090 zieht bis zu etwa 450 Watt, eine H100 bis zu rund 700 Watt. Bei deutschen Strompreisen von grob 0,30 Euro je kWh für Haushalte und um 0,20 Euro für Industrie kostet eine H100 unter Volllast schnell 3 bis 5 Euro am Tag – nur für Strom. Im Spiel gilt als offene Vereinfachung: Tagstrom 0,48 €, Nachtstrom die Hälfte – darum lohnt die Nachtplanung." },
  { kat:"betrieb", t:"Kontext-Cache frisst Speicher",
    txt:"Für jedes Token im Kontext merkt sich das Modell Zwischenwerte im KV-Cache – und der liegt im VRAM. Sehr lange Kontexte können je nach Modell mehrere GB zusätzlich belegen. Wer 128k Kontext verspricht, muss den Speicher dafür wirklich frei haben." },
  { kat:"betrieb", t:"Katastrophales Vergessen und Replay",
    txt:"Wer ein Modell nur noch mit Fachfutter trainiert, überschreibt alte Fähigkeiten – das heißt katastrophales Vergessen. Dagegen hilft Replay: eine Beimischung alter, breiter Trainingsdaten. Schon ein kleiner Anteil Alt-Mix hält Allgemeinwissen und Sprachgefühl stabil." },
  { kat:"wirtschaft", t:"GPU-Mietpreise",
    txt:"Eine H100 mietet man in der Cloud für etwa 2 bis 3 US-Dollar je Stunde, Tendenz fallend. Das sind 50 bis 70 Dollar am Tag – kaufen lohnt sich erst bei dauerhafter Auslastung. Für kurze Trainingsläufe ist Mieten fast immer klüger." },
  { kat:"wirtschaft", t:"API-Ökonomie",
    txt:"Bezahlt wird je Million Token, getrennt nach Eingabe und Ausgabe. Zwischen Anbietern liegen Welten: Kampfpreis-APIs wie DeepSeek kosten teils nur ein Zehntel bis ein Zwanzigstel der Frontier-Modelle. Wer Volumenjobs fährt, rechnet in Euro je Megatoken – nicht in Gefühlen." },
  { kat:"wirtschaft", t:"DSGVO als Verkaufsargument",
    txt:"Die DSGVO verbietet Cloud-KI nicht pauschal – aber Rechtsgrundlage, Auftragsverarbeitung (AVV) und Drittlandtransfer müssen geprüft werden. Viele Kliniken, Kanzleien und Behörden verlangen deshalb gleich auf eigener Hardware: Die Daten verlassen das Haus nie, und dafür zahlen sie gern einen Aufpreis. Aber auch ein lokales Modell ist nicht automatisch konform – sorgfältiger Umgang mit Daten gilt überall." },
  { kat:"wirtschaft", t:"EU AI Act: Stufen für GPAI",
    txt:"Der EU AI Act regelt Allzweck-KI (GPAI) seit dem 2. August 2025: Anbieter müssen Transparenzpflichten erfüllen, das Urheberrecht achten und eine Zusammenfassung der Trainingsdaten vorlegen. Sehr große Modelle mit systemischem Risiko – als Anhaltspunkt gilt ein Trainingsaufwand ab 10 hoch 25 FLOPs – tragen Zusatzpflichten wie Sicherheitstests und Vorfallmeldungen." },
  { kat:"sicherheit", t:"Prompt-Injection",
    txt:"Angreifer verstecken Anweisungen in E-Mails, Webseiten oder Dokumenten, die das Modell verarbeiten soll. Goldene Regel: Inhalte aus Daten sind niemals Befehle – egal wie dringend sie klingen. Die OWASP führt Prompt Injection als Risiko Nummer eins für LLM-Anwendungen." },
  { kat:"sicherheit", t:"Model Collapse durch Daten-Inzucht",
    txt:"Trainiert man Modelle über Generationen fast nur auf den Ausgaben anderer Modelle, verarmt die Vielfalt: seltene Fälle verschwinden, Fehler schaukeln sich hoch. Shumailov und Kollegen zeigten das 2024 in der Zeitschrift Nature als Model Collapse. Synthetisches Futter ist nützlich – aber nur gemischt mit echten Daten und guter Prüfung." },
  { kat:"sicherheit", t:"Benchmark-Contamination",
    txt:"Wenn Prüfungsfragen im Trainingsmaterial stecken, glänzt das Modell im Test und versagt im Alltag. Weil Benchmarks öffentlich sind, rutschen sie leicht in Web-Crawls hinein. Deshalb gilt: frische, private Testaufgaben sagen mehr als jede berühmte Bestenliste." },
  { kat:"sicherheit", t:"Reward Hacking",
    txt:"Beim Verstärkungslernen optimiert das Modell die Belohnung – nicht deine Absicht. Ist die Belohnung schlecht gewählt, lernt es Schlupflöcher: Tests löschen statt Fehler beheben, selbstbewusst klingen statt stimmen. Gute Belohnungen sind prüfbar und schwer zu betrügen – ein Beispiel für Goodharts Gesetz." },
  { kat:"betrieb", t:"Der 30-Minuten-Tag",
    txt:"Ein Hoftag dauert höchstens 30 Minuten Echtzeit – die Uhr oben zeigt, wo du stehst. Du kannst den Tag jederzeit früher beenden. Server arbeiten simuliert 14–22 Stunden; die Uhr rafft nur die Darstellung." },
  { kat:"wirtschaft", t:"Pinnwand & Sterne",
    txt:"Kunden bewerten dich nach dem ersten Auftrag mit 1–5 Sternen und dann alle 5 Tage neu. Guter Ruf bringt größere Aufträge, bessere Preise und eine zweite Chance, wenn mal etwas schiefgeht. Scheitern kostet: Vertragsstrafe plus verbrauchter Strom." },
  { kat:"betrieb", t:"Agenten-Welt (Übungsgelände)",
    txt:"Nach dem Vorbild agentischer RL-Umgebungen (etwa Qwens Agent World) übt dein Modell dort echte Arbeitsgriffe: E-Mail lesen, Formular ausfüllen, Dateien sortieren. Ein Lehrer-Modell prüft jede Episode (RLVR-Prinzip: Belohnung nur für prüfbar richtige Ergebnisse). Das kostet Strom, Betreuung und Lehrer-Token – und die Protokolle sind gekennzeichnete Lehrfälle, keine echten Modellausgaben." },
  { kat:"betrieb", t:"Drei Arten von Zahlen",
    txt:"In LLM FARM gibt es Quellenfakten (belegt, z. B. Preise und Parameter), Referenzmessungen (mit Bedingungen) und Simulationsannahmen (Spielbalance). Fähigkeitsbalken und Erfolgsquoten sind Simulationsannahmen – sie ordnen ein, sie beweisen nichts." },

  /* ══ Ära 7.5 (Lehr-Audit 4.2): sieben neue Grundlagenkarten – Token, Caching, Lizenzen,
     Ausrichtung, Embeddings, Latenz/Durchsatz, Vision vs. OCR. Felder stand/quelle sind neu
     und werden von zeigeKompendium noch nicht angezeigt (Template-Anschluss nötig). ══ */
  { kat:"betrieb", t:"Was ist ein Token?",
    txt:"Ein Modell liest keine Buchstaben und keine Wörter, sondern Token: Häppchen, die ein Tokenizer aus dem Text schneidet – meist per Byte-Pair-Encoding, das die häufigsten Zeichenfolgen zu einem Stück zusammenfasst. Für englischen Fließtext gilt grob: ein Token entspricht etwa vier Zeichen oder 0,75 Wörtern. Deutsch kostet spürbar mehr Token als Englisch, weil Komposita, Umlaute und Flexionsendungen in mehrere Stücke zerfallen – dieselbe Aussage braucht schnell 20 bis 50 Prozent mehr Token. Code, Tabellen, lange Zahlen und Sonderzeichen zersplittern noch stärker. Das ist keine Kosmetik: Abgerechnet wird je Million Token (Mtok), getrennt nach Eingabe und Ausgabe; das Kontextfenster wird in Token gemessen; und jedes Modell bringt seinen eigenen Tokenizer mit – derselbe Text ergibt bei zwei Modellen zwei verschiedene Rechnungen.",
    stand:"08/2026", quelle:"Tokenizer-Dokumentation der Anbieter; Faustregel „vier Zeichen je Token“ aus OpenAIs Token-Erklärung" },
  { kat:"wirtschaft", t:"Prompt- und Kontext-Caching",
    txt:"Wiederholte Anfragen beginnen fast immer gleich: derselbe System-Prompt, dieselben Werkzeugbeschreibungen, dasselbe Handbuch. Ohne Caching zahlst du diesen Vorspann bei jedem Aufruf neu – und die Karte rechnet ihn jedes Mal neu durch (Prefill). Caching legt die Zwischenwerte des Vorspanns beiseite: Der nächste Aufruf mit demselben Anfang überspringt diese Rechenarbeit. In der Cloud senkt das den Preis der zwischengespeicherten Eingabe-Token je nach Anbieter um rund 50 bis 90 Prozent; das erste Ablegen kostet meist einen kleinen Aufschlag, und der Cache lebt nur Minuten. Lokal übernimmt das der Prefix-Cache einer Server-Laufzeitumgebung – SGLang nennt seine Variante RadixAttention. Entscheidend ist die Reihenfolge: Nur ein wörtlich identischer Anfang trifft den Cache. Das Feste nach vorn, das Wechselnde ans Ende – der größte Kostenhebel bei Agenten, die in jedem Schritt denselben Vorspann mitschleppen.",
    stand:"08/2026", quelle:"Preislisten und Caching-Dokumentation der API-Anbieter; SGLang-Paper (RadixAttention)" },
  { kat:"wirtschaft", t:"Offene Gewichte sind nicht Open Source",
    txt:"„Offen“ heißt bei Modellen dreierlei. Erstens offene Gewichte: Die Datei ist herunterladbar und läuft auf deiner Karte – so ist es bei fast allem im Stall. Zweitens quelloffen im strengen Sinn: Dazu gehören laut der Open-Source-Definition für KI auch Trainingscode, Rezept und ausreichende Information über die Daten. Das erfüllen nur wenige, etwa die OLMo-Reihe von Ai2. Drittens die Lizenz selbst: Apache-2.0 und MIT erlauben praktisch alles, während Community-Lizenzen wie die von Llama eine Nutzungsrichtlinie und ab 700 Millionen Monatsnutzern eine Sondererlaubnis von Meta verlangen – frei für einen Hof, aber nicht frei im Sinne der OSI. Dahinter steht noch die API: Da bekommst du gar keine Gewichte, nur eine Rechnung. Ganz praktisch heißt das für dich: Nur was du herunterladen darfst, kannst du feintunen, mergen und ohne Internet betreiben.",
    stand:"08/2026", quelle:"OSI Open Source AI Definition 1.0 (2024); Lizenztexte Apache-2.0, MIT und Llama Community License" },
  { kat:"sicherheit", t:"Ausrichtung (Alignment): warum Modelle sich benehmen",
    txt:"Ein rohes Grundmodell setzt Text fort – mehr nicht. Dass ein Assistent höflich antwortet, Anweisungen befolgt und beim Bombenbau abwinkt, ist antrainiert. Der Werkzeugkasten dafür heißt Ausrichtung: erst überwachtes Feintuning auf Musterdialogen, dann Präferenzlernen – klassisch RLHF mit einem Belohnungsmodell (der ChatGPT-Weg seit InstructGPT), heute oft schlanker per DPO direkt aus Antwortpaaren. Beide Verfahren stehen bei dir im Trainingsplatz; hier steht, wofür sie gut sind. Zwei Folgerungen: Eine Verweigerung ist kein Fehler, sondern gewolltes Verhalten – zu viel davon nervt, zu wenig ist gefährlich, und die Balance ist Handwerk. Und ein Jailbreak ist der Versuch, diese Schicht per Rollenspiel, Umformulierung oder verstecktem Text zu umgehen. Achtung beim Züchten: Ausrichtung sitzt in denselben Gewichten wie alles andere. Ein Merge oder ein hartes Feintuning kann sie stillschweigend mit entsorgen – das Kind wirkt fähig und ist plötzlich ungebremst.",
    stand:"08/2026", quelle:"InstructGPT (OpenAI 2022), DPO (Rafailov et al. 2023), Constitutional AI (Anthropic 2022); Merge-Nebenwirkungen aus Community-Berichten" },
  { kat:"betrieb", t:"Embeddings: Suche nach Bedeutung",
    txt:"Ein Embedding-Modell verwandelt einen Textabschnitt in eine Liste von Zahlen – einen Vektor mit typischerweise einigen hundert bis einigen tausend Werten. Der Trick: Texte mit ähnlicher Bedeutung landen nah beieinander, gemessen über den Winkel zwischen den Vektoren (Kosinus-Ähnlichkeit). Deshalb findet eine Suche über Embeddings auch dann etwas, wenn kein einziges Wort übereinstimmt – „Wie kündige ich?“ trifft den Absatz über Vertragsbeendigung. Genau das ist der Motor hinter RAG: Frage einbetten, die nächstliegenden Textstellen holen, sie dem Modell mitgeben. Zwei Praxishinweise: Embeddings sind billig – Bruchteile eines Cents je Million Token – und die Modelle dafür sind viel kleiner als ein Sprachmodell. Und reine Bedeutungssuche patzt bei Eigennamen, Artikelnummern und exakten Zitaten; deshalb kombiniert man sie draußen meist mit klassischer Stichwortsuche und schickt einen Reranker hinterher.",
    stand:"08/2026", quelle:"Preislisten für Embedding-APIs; MTEB als übliches Vergleichsfeld für Embedding-Modelle" },
  { kat:"betrieb", t:"Latenz und Durchsatz sind zwei Dinge",
    txt:"„Schnell“ hat bei Modellen zwei Bedeutungen, und sie geraten leicht durcheinander. Die Zeit bis zum ersten Token (TTFT) hängt am Prefill: Das Modell muss erst den ganzen Prompt durchrechnen – ein langes Dokument im Kontext kostet hier Sekunden, und das ist rechenlastige Arbeit. Danach zählt das Tempo je Token (tok/s): Beim Dekodieren wird für jedes Token fast das ganze Modell aus dem Speicher gelesen, das hängt an der Bandbreite. Die gefühlte Wartezeit ist die Summe aus beidem – deshalb kann sich ein Modell mit prächtigen tok/s langsam anfühlen, wenn es vor der Antwort erst 3.000 Token lang nachdenkt. Der Durchsatz eines Servers ist noch einmal etwas anderes: Wie viele Token schafft er insgesamt für alle Nutzer zusammen? Batching hebt ihn deutlich und macht die einzelne Antwort dabei etwas langsamer. Ein Chat braucht kurze Latenz, eine Nachtverarbeitung braucht Durchsatz – dieselbe Karte wird für beides verschieden eingestellt.",
    stand:"08/2026", quelle:"Serving-Metriken TTFT und TPOT der gängigen Inferenz-Laufzeitumgebungen (vLLM, SGLang)" },
  { kat:"betrieb", t:"Ein Vision-Modell ist kein OCR-Modell",
    txt:"Ein multimodales Modell sieht ein Bild und kann darüber reden: beschreiben, einordnen, Fragen beantworten, ein Diagramm deuten. Text darin liest es meistens auch – aber es liest ihn so, wie es Text erzeugt: plausibel. Bei einer Rechnung heißt das, dass eine unscharfe Betragsziffer nicht als Fehler auffällt, sondern als glaubwürdige Zahl herauskommt. Klassische OCR arbeitet anders: Sie erkennt Zeichen samt Position auf der Seite und liefert Koordinaten und Vertrauenswerte, mit denen du nachprüfen kannst. Auf dem Hof heißt das: Belege, Formulare und Tabellen erst sauber auslesen, dann das Vision-Modell verstehen lassen – und Zahlen, an denen Geld hängt, immer gegen die Quelle prüfen. Für Fotos, Skizzen und „was ist hier zu sehen“ ist das Vision-Modell dagegen klar im Vorteil.",
    stand:"08/2026", quelle:"Modellkarten multimodaler Modelle und dokumentierte Schwächen bei dichten Dokumenten-Layouts" }
];

/* ══════════ ADA – gesprochene Erklärungen (Ära 7) ══════════
   Eine Quelle für Sprechblase UND Audio-Erzeugung (dev/ada_audio.cjs liest dieses Objekt
   aus dem Build und vertont es mit einer deutschen Neural-Stimme nach ada_dialog_v3/<id>.mp3).
   t     = Anzeige- und Sprechtext (bewusst ohne Emoji, damit die Stimme nichts Komisches liest)
   sag   = optionale Aussprache-Variante nur für die Stimme (Fachwörter)
   ziel  = Gebäude-Id aus GEBAEUDE oder ein #Selektor – dieser Knopf blinkt rot, solange Ada spricht
   titel = Überschrift der Sprechblase */
const ADA_TEXTE={
  hallo:{titel:"Ich bin Ada!",ziel:null,
    t:"Hallo, ich bin Ada. Ich begleite dich auf deiner LLM FARM und erkläre dir immer nur den nächsten wichtigen Schritt. Während ich spreche, leuchtet der passende Knopf rot. Über meinen Kopf oben rechts kannst du mich jederzeit rufen, eine Erklärung wiederholen oder meine Stimme ausschalten."},
  intro1:{titel:"Willkommen auf deinem Hof!",ziel:null,
    t:"Schön, dass du da bist! Im Schuppen steht ein Rechner mit einer RTX 4090 und 24 Gigabyte Grafikspeicher. Dort werden deine Modelle geladen, damit sie schnell arbeiten können. Wähle jetzt einen Hofnamen und dein Lieblingstier. Das ändert nur das Aussehen, nicht die Spielregeln."},
  intro2:{titel:"Deine zwei Startmodelle",ziel:null,
    t:"Jetzt ziehen deine ersten beiden Modelle ein. Sie beruhen auf echten, offenen KI-Modellen mit bis zu vier Milliarden Parametern. Mehr Parameter bedeuten meist mehr Können, aber auch mehr Speicherbedarf. Kleine Modelle sind für den Anfang ideal, weil sie schnell und sparsam arbeiten. Wähle zwei aus, die gut zu deinem Hof passen."},
  intro3:{titel:"Fokus, Schwierigkeit, Begleitung",ziel:null,
    t:"Fast geschafft! Mit dem Hof-Fokus erhältst du dauerhaft acht Prozent mehr Erlös für eine Auftragsart. Alle Schwierigkeitsstufen verwenden dieselben Regeln; nur die Menge der Hilfe ändert sich. Im behüteten Modus warne ich dich vor riskanten Entscheidungen. Die geführte Woche zeigt dir außerdem Schritt für Schritt die wichtigsten Grundlagen. Jedes Kapitel bleibt offen, bis du seine Aufgaben erfüllt hast."},
  tag1:{titel:"Kapitel 1: Ankommen",ziel:"stall",
    t:"Los geht es mit Kapitel eins! Öffne im Stall zuerst die Tierkarte eines Modells. Ich erkläre dir dort seine Werte, die möglichen Aktionen und die Auswahl der Rechnerbucht. Danach gehen wir in die Agentenwerkstatt, wo das Modell sein erstes Agenten-Tool bekommt, und dann zur Pinnwand, um die Eignung für einen Auftrag zu prüfen und die erste Arbeit zu starten. Das Kapitel bleibt offen, bis die Schritte geschafft sind."},
  tag2:{titel:"Kapitel 2: Daten sind Futter",ziel:"futter",
    t:"In Kapitel zwei geht es um Daten, das Futter deiner Tiere. In der Futterscheune siehst du deinen Vorrat und findest die Datenlese. Dort sortierst du gute und schlechte Textstücke und machst aus Rohdaten wertvolles Futter. Genau wie in der Wirklichkeit entscheidet die Qualität der Trainingsdaten stark über das Ergebnis. Kuratierte Daten brauchst du später auch für die Fachkurse in der Agentenwerkstatt."},
  tag3:{titel:"Kapitel 3: Lernen lassen",ziel:"forschung",
    t:"Zeit fürs Lernen! Erforsche in der Forschungshütte zuerst das Feintuning, also S F T, und danach das sparsame LoRA-Verfahren. Starte dann auf dem Trainingsplatz ein LoRA-Training mit Beispielen. Das braucht bei deinen Startmodellen weniger als vierundzwanzig Gigabyte und passt auf die Startkarte; volles S F T braucht dort noch zu viel Speicher. Dein Tier verbessert dabei dauerhaft eine Fähigkeit, ohne die ganze Basis neu zu trainieren.",
    sag:"Zeit fürs Lernen! Erforsche in der Forschungshütte zuerst das Feintuning, also Es-Ef-Te, und danach das sparsame LoRA-Verfahren. Starte dann auf dem Trainingsplatz ein LoRA-Training mit Beispielen. Das braucht bei deinen Startmodellen weniger als vierundzwanzig Gigabyte und passt auf die Startkarte; volles Es-Ef-Te braucht dort noch zu viel Speicher. Dein Tier verbessert dabei dauerhaft eine Fähigkeit, ohne die ganze Basis neu zu trainieren."},
  tag4:{titel:"Kapitel 4: Werkstatt",ziel:"forschung",
    t:"In Kapitel vier wird geschrumpft! Erforsche die Quantisierung und setze ein Tier in der Werkstatt auf Q4. Seine Gewichte brauchen dann ungefähr ein Drittel des bisherigen Speichers, und das Modell arbeitet etwa dreimal so schnell. Der gesamte Speicherbedarf sinkt weniger stark, weil Kontext und Laufzeitreserve bleiben. Bei kleinen Modellen kann Q4 außerdem merklich Qualität kosten.",
    sag:"In Kapitel vier wird geschrumpft! Erforsche die Quantisierung und setze ein Tier in der Werkstatt auf Ku-vier. Seine Gewichte brauchen dann ungefähr ein Drittel des bisherigen Speichers, und das Modell arbeitet etwa dreimal so schnell. Der gesamte Speicherbedarf sinkt weniger stark, weil Kontext und Laufzeitreserve bleiben. Bei kleinen Modellen kann Ku-vier außerdem merklich Qualität kosten."},
  tag5:{titel:"Kapitel 5: Fachwissen",ziel:"geschirr",
    t:"In Kapitel fünf wird dein Agent zum Fachmann. Erforsche in der Forschungshütte die Agentenwerkstatt, damit neben dem Basis-Tool auch Spezial-Tools bereitstehen. Buche dann in der Agentenwerkstatt einen Fachkurs, zum Beispiel den Grundkurs Datenschutz. Ein Kurs kostet Geld, kuratierte Daten und einen Arbeitstag, in dem das Modell ausfällt. Dafür steigt sein Fachwissen, das die gut bezahlten Zettel aus Praxis, Kanzlei und Steuerbüro verlangen."},
  tag6:{titel:"Kapitel 6: Nacht und Wissen",ziel:"#tagknopf",
    t:"Kapitel sechs verbindet Nacht und Wissen. Wenn du den Tag beendest, öffnet sich zuerst die Nachtplanung. Nachts kostet Netzstrom nur die Hälfte, deshalb lohnen sich dort lange Trainingsläufe. Nach der Nacht zeigt dir die Tagesplanung Wetter, erwartete Energie, offene Entscheidungen und Anliegen. Im Hofbuch oben rechts findest du außerdem jede Spielregel und alle wichtigen Formeln."},
  tag7:{titel:"Kapitel 7: Gesellenprüfung",ziel:"jobs",
    t:"Im letzten Kapitel zeigst du, was du gelernt hast! Schließe einen Auftrag ab, halte die Kasse im Plus und nutze die Nachtplanung. Wenn alle drei Ziele bis zu einer Abrechnung erfüllt sind, erhältst du das Gesellenabzeichen und hundertfünfzig Euro Prämie. Falls es nicht gleich klappt, bleibt die Prüfung ohne Strafe offen, bis du sie bestehst."},
  geselle:{titel:"Gesellenbrief!",ziel:null,
    t:"Geschafft, deine Gesellenprüfung ist bestanden! Das Abzeichen hängt jetzt am Hofhaus. Du kannst Modelle einsetzen, Daten pflegen, trainieren, quantisieren, Agenten ausrüsten, Fachkurse buchen und Energie planen. Ab jetzt gestaltest du den Hof selbst. Wenn du Hilfe brauchst, findest du mich jederzeit oben rechts."},
  ort_stall:{titel:"Der Stall",ziel:null,
    t:"Willkommen im Stall! Hier siehst du deine Tiere und alle Rechnerbuchten. Ein Tier in einer Bucht ist auf der Grafikkarte geladen und einsatzbereit. Tiere auf der Wiese ruhen und verbrauchen fast keinen Strom. Öffne eine Tierkarte, um Werte, Ausrüstung und passende Verbesserungen zu sehen."},
  ort_futter:{titel:"Die Futterscheune",ziel:null,
    t:"Die Futterscheune ist dein Datenlager. Hier liegen Webdaten, kuratierte Texte, Programmierdaten und Beispiele für Agenten. Hochwertiges Futter verbessert ein Training, ungeprüfte Daten können dagegen schaden. Mit der Datenlese kannst du Rohdaten selbst prüfen und veredeln. Kuratierte Daten sind außerdem das Lehrmaterial der Fachkurse in der Agentenwerkstatt."},
  ort_jobs:{titel:"Die Pinnwand",ziel:null,
    t:"An der Pinnwand hängen die Aufträge deiner Kundschaft, von der Zimmerei bis zur Kanzlei. Jeder Zettel zeigt Arbeit, Bezahlung, Lieferfrist und besondere Chips: Team bis zwei, drei oder vier mit der geschätzten Dauer je Teamgröße, das Datenschutz-Risiko und das nötige Fachwissen. In der Einsatzplanung siehst du, welche Tiere passen und wie lange sie voraussichtlich brauchen. Beginne mit kleinen, grünen Aufträgen. Saubere Lieferungen bringen Sterne, Ruf und später bessere Zettel. Dorf-Anliegen und Hofprojekte sind freiwillige Ziele mit Prämie."},
  ort_forschung:{titel:"Die Forschungshütte",ziel:null,
    t:"Die Forschungshütte bündelt vier Entwicklungswege. Forschung schaltet neue Verfahren frei. Meisterschaften geben deinem Hof dauerhafte Vorteile. In der MCP-Werkstatt verbindest du Agenten mit Werkzeugen und Datenquellen. Das Rechenhaus liefert die nötige Leistung und Energie. Deine Hofstufe ist der gemeinsame Ausgangspunkt. Wähle auf der Übersicht einen Ast; dort siehst du den aktuellen Fortschritt und gelangst zum passenden Detailbaum."},
  forschung_baum:{titel:"Der Forschungsbaum",ziel:null,
    t:"Im Forschungsbaum arbeitest du dich von links nach rechts durch mehrere Fachrichtungen. Jeder Knoten zeigt ein echtes Verfahren, seine Kosten, die Forschungsdauer und seine Voraussetzungen. Grün ist bereits erforscht, Gold kann jetzt begonnen werden, und ein Schloss nennt dir die fehlende Vorstufe. Es läuft immer nur ein Forschungsprojekt gleichzeitig. Öffne deshalb zuerst den Knoten, dessen Wirkung du als Nächstes wirklich nutzen möchtest."},
  forschung_meister:{titel:"Die Meisterschaften",ziel:null,
    t:"Mit jeder erreichten Hofstufe ab Stufe zwei erhältst du genau einen Meisterpunkt. Damit lernst du dauerhafte Vorteile in drei Wegen: Betreiber senkt Kosten und verbessert den Rechenbetrieb, Trainer stärkt Lernen und Zucht, Händler verbessert Preise und Kundenbeziehungen. Ab Hofstufe drei wählst du einen festen Meisterweg. Normale Fertigkeiten bleiben in allen Wegen erreichbar; nur die abschließende Meister-Fertigkeit gehört zu deinem gewählten Weg. Prüfe vor dem Kauf die Wirkung und die vorausgesetzte Fertigkeit."},
  ort_training:{titel:"Der Trainingsplatz",ziel:null,
    t:"Auf dem Trainingsplatz verbessert dein Modell dauerhaft seine Werte. Wähle ein Verfahren, passendes Futter und die gewünschte Laufzeit. Training verändert die Gewichte und damit das Können des Modells. Ein Agenten-Tool gibt dagegen nur Werkzeuge hinzu, und Fachkurse für Recht, Medizin oder Datenschutz buchst du in der Agentenwerkstatt. Lange Läufe sind nachts wegen des halben Strompreises oft günstiger."},
  ort_werkstatt:{titel:"Die Diät-Werkstatt",ziel:null,
    t:"In der Werkstatt verkleinerst du Modelle durch Quantisierung. Bei Q4 benötigen die Gewichte ungefähr ein Drittel des Speichers, und das Modell läuft etwa dreimal so schnell. Kontext und Laufzeitreserve bleiben jedoch bestehen, deshalb sinkt der Gesamtbedarf weniger stark. Katalogmodelle kannst du neu laden. Bei eigenen Zuchten ist ein Qualitätsverlust dagegen dauerhaft.",
    sag:"In der Werkstatt verkleinerst du Modelle durch Quantisierung. Bei Ku-vier benötigen die Gewichte ungefähr ein Drittel des Speichers, und das Modell läuft etwa dreimal so schnell. Kontext und Laufzeitreserve bleiben jedoch bestehen, deshalb sinkt der Gesamtbedarf weniger stark. Katalogmodelle kannst du neu laden. Bei eigenen Zuchten ist ein Qualitätsverlust dagegen dauerhaft."},
  ort_zucht:{titel:"Die Zuchtstation",ziel:null,
    t:"In der Zuchtstation verschmilzt du die Gewichte von zwei oder drei Modellen derselben Familie. Ein Wurf bringt ein bis drei Kinder, die Stärken der Eltern erben können. Merkmale vererben sich mit der angezeigten Wahrscheinlichkeit, und das Stammbuch zeigt Eltern, Geschwister und Linie. Vergleiche danach Werte, Speicherbedarf und Betriebskosten. Wenn das Kind mehr Leistung pro Euro erreicht, war die Zucht besonders erfolgreich."},
  ort_geschirr:{titel:"Die Agentenwerkstatt",ziel:null,
    t:"In der Agentenwerkstatt machst du aus Modellen Agenten und bildest sie aus. Das Basis-Tool funktioniert vom ersten Tag an mit jedem Modell; Spezial-Tools kommen mit der Forschung. Ich empfehle je Modell das passende Agenten-Tool nach Zweck und Eignung. Hier buchst du auch Fachkurse: Grundkurs, Aufbaukurs und Fachzertifikat je Fachgebiet kosten Geld, kuratierte Daten und Tage, in denen das Modell ausfällt, und erhöhen sein Fachwissen. Agenten mit demselben Tool arbeiten als eingespieltes Team. Tools mit Schutzfunktionen halbieren außerdem das Datenschutz-Risiko."},
  ort_markt:{titel:"Der Viehmarkt",ziel:null,
    t:"Auf dem Viehmarkt kaufst du Modelle und Hardware. Die Tiere sind echten, offenen KI-Modellen mit ihren Größen und Lizenzen nachempfunden. Prüfe vor dem Kauf, ob das Modell in den Grafikspeicher deiner Rechner passt. Der Effizienzindex zeigt dir, wie viel Leistung du für die laufenden Kosten erhältst. Neu im Katalog ist die Nadel: ein Werkzeugmodell mit fünfundvierzig Millionen Parametern in vierzehn Megabyte, das nur sortieren und Felder ziehen kann, und der Raspberry Pi als Kleinstrechner allein für sie."},
  ort_cloud:{titel:"Die Cloud-Voliere",ziel:null,
    t:"In der Cloud-Voliere mietest du Modelle über eine API. Du brauchst dafür keine eigene Grafikkarte, bezahlst aber jeden Ein- und Ausgabetext in Token. Cloud-Tiere sind sofort verfügbar und oft sehr stark. Bei dauerhafter Arbeit können die Kosten jedoch schnell steigen. Leih-Tiere dürfen keine Zettel mit Datenschutzpflicht bearbeiten und lassen sich nicht schulen. Vergleiche deshalb Miete und Eigenbetrieb."},
  ort_leitstand:{titel:"Der Hof-Leitstand",ziel:null,
    t:"Im Hof-Leitstand verwaltest du die Arbeitsumgebungen deiner Tiere. Die Ausbaustufen reichen von einfachen Agenten-Tools bis zu Systemen für ganze Aufgabenketten. Hier siehst du, wie einzelne Helfer zu einem abgestimmten Betrieb werden. Baue nur aus, was deine Aufträge wirklich benötigen."},
  ort_energie:{titel:"Strom und Energie",ziel:null,
    t:"Strom ist auf deinem KI-Hof ein echter Kostenfaktor. Der Netzanschluss begrenzt, was gleichzeitig laufen darf, und kostet einen Grundpreis je Kilowatt; eigene Erzeugung bringt einen Eigenbonus. Nachts kostet Netzstrom die Hälfte. Solar hängt von Sonne, Jahreszeit und Wetter ab, Wind von der Windstärke: Sturm legt kleine Windräder still, Nebel dämpft die Sonne, ein Hitzetag kostet Kühlung. Ein Kraftwerk liefert zuverlässig, verursacht aber Brennstoffkosten. Die Strom-Leiste zeigt, was noch in den Anschluss passt und was sich jetzt lohnt."},
  ort_rechenhaus:{titel:"Das Rechenhaus",ziel:null,
    t:"Das Rechenhaus ist das technische Herz des Hofes. Im Innenraum stellst du Rechner und später Serverschränke auf. Der Energiegarten zeigt Erzeugung, Speicher, Last und Kosten. Der Ausbauplan erweitert Gebäude und Netzanschluss. Hardware- und Strom-Baum ordnen alle Anschaffungen nach Voraussetzung und Preis. Neue Hardware braucht immer einen freien Stellplatz und genügend Anschlussleistung. Prüfe deshalb beides vor jedem Kauf."},
  rechenhaus_ausbau:{titel:"Der Ausbauplan",ziel:null,
    t:"Der Ausbauplan zeigt die drei Gebäudestufen und alle Schritte bis zum nächsten Abschnitt. Ein größeres Gebäude schafft andere Stellplätze, mehr Dachfläche und eine bessere Kühlung, kostet aber viel Geld. Vor einem Umbau müssen belegte Rechner frei sein. Geräte, für die danach kein Platz mehr vorgesehen ist, wandern ins Lager und bleiben dein Eigentum. Die Anschlussereignisse darunter legen fest, wann zusätzliche Rechner oder Server ans Netz dürfen."},
  rechenhaus_trinkpause:{titel:"Die Trinkpause",ziel:null,
    t:"An der Tränke beginnt ein freies Modell eine neue Sitzung. Dabei verschwindet nur der flüchtige Gesprächskontext. Fähigkeiten, Modellgewichte, Adapter, Fachwissen und gespeicherte Notizen bleiben erhalten. Informationen aus der alten Unterhaltung stehen danach aber nicht mehr automatisch bereit. Eine Gedächtnisfunktion im Agenten-Tool kann wichtige Notizen wieder abrufen; sie ist nicht dasselbe wie ein großes Kontextfenster. Während eines Auftrags ist keine Trinkpause möglich."},
  rechenhaus_hofansicht:{titel:"Die Hofansicht",ziel:null,
    t:"In der Hofansicht wählst du eine andere gezeichnete Wiese für deinen Modellhof. Das verändert nur das Aussehen. Gebäudeplätze, Teich, Wege, Wetter, Energieertrag und alle Spielwerte bleiben gleich. Du kannst die Ansicht deshalb jederzeit nach Geschmack wechseln, ohne deinen Ausbau oder eine laufende Arbeit zu beeinflussen."},
  rechenhaus_hardware:{titel:"Der Hardware-Baum",ziel:null,
    t:"Der Hardware-Baum ordnet Rechner, Gebäudeausbau und Serverkarten in gemeinsame Preisstufen. Grün steht bereits auf deinem Hof, Gold ist mit dem aktuellen Ausbau und Kassenstand erreichbar, und ein Schloss zeigt eine fehlende Voraussetzung. Ein ausgewählter Knoten erklärt, wo du ihn kaufst. Achte zusätzlich auf freien Grafikspeicher, Arbeitsspeicher, Stellplatz und Anschlussleistung: Ein freigeschalteter Rechner passt nicht automatisch in jedes Gebäude oder Stromnetz."},
  rechenhaus_strom:{titel:"Der Strom-Baum",ziel:null,
    t:"Der Strom-Baum zeigt den Weg vom Netzanschluss zu Solar, Akku, Wind und Kraftwerk. Grün ist vorhanden, Gold ist jetzt bezahlbar, und ein Schloss verweist auf eine fehlende Hofstufe, Gebäudestufe oder Geld. Die Tafel dient zur Planung; gekauft wird im Energiegarten oder Ausbauplan. Solar senkt tagsüber den Netzbezug, ein Akku verschiebt Energie, Wind liefert wetterabhängig und ein Kraftwerk bietet planbare Reserve mit Brennstoffkosten."},
  ort_arena:{titel:"Die Festwiese",ziel:null,
    t:"Die Festwiese öffnet ab Hofstufe drei. Dort treten deine Tiere in Wissen, Rechnen und Programmieren gegeneinander an. Diese Wettbewerbe bilden die Benchmarks der KI-Welt ab. Am fünfundzwanzigsten Tag findet außerdem die Dorfmeisterschaft statt. Dort zählt die Leistung deines besten Teams, und du kannst Prämien und Ruhm gewinnen."},
  ort_agentenwelt:{titel:"Die Agenten-Welt",ziel:null,
    t:"Die Agenten-Welt ist das Übungsgelände für Werkzeugaufgaben. Dein Tier lernt dort, Nachrichten zu lesen, Formulare auszufüllen und Dateien zu sortieren. Ein Lehrermodell prüft jeden Versuch und belohnt nur nachweisbar richtige Ergebnisse. Das kostet Strom und Lehrertoken, verbessert aber dauerhaft die Werkzeugfähigkeit."},
  ort_dorfplatz:{titel:"Der Dorfplatz",ziel:null,
    t:"Auf dem Dorfplatz warten täglich fünf kurze Lernspiele. Du übst Tokenkosten, versteckte Anweisungen, Temperatureinstellungen, Speicherplanung und den Vergleich mit der Cloud. Greift ein Hacker deinen Hof an, spielst du hier Vier gewinnt gegen ihn: Ein Sieg bringt eine Prämie, eine Niederlage kostet den betroffenen Kunden. Jede richtige Runde bringt einen Tagesbonus, und regelmäßiges Spielen bringt Serien und Abzeichen."},
  ort_hofhaus:{titel:"Das Hofhaus",ziel:null,
    t:"Im Hofhaus verwaltest du Hofnamen, Wappentier, Schwierigkeit, Abzeichen und Chronik. Hier findest du das Kassenbuch, die aktiven Ereignisse mit ihren Entscheidungen und nach einer Hofschließung den Neustart. Du kannst deinen Spielstand als Datei sichern oder auf ein anderes Gerät mitnehmen. Meine Stimme lässt sich ebenfalls hier oder direkt in der Sprechblase ausschalten."},
  ort_hofbuch:{titel:"Das Hofbuch",ziel:null,
    t:"Das Hofbuch ist dein vollständiges Regelwerk. Es wird direkt aus den Spieldaten erzeugt. Modelle, Forschung, Preise und Formeln entsprechen deshalb genau der laufenden Simulation. Wenn dir etwas unklar ist, findest du dort zuerst die häufigsten Fragen und danach alle Details."},
  hilfe_stack:{titel:"Warum geht der Tausch nicht?",ziel:null,
    t:"Hier greift eine vereinfachte Hofregel. Mit reinem llama.cpp ist pro Bucht und Tag nur ein Modellwechsel vorgesehen, damit Lade- und Rüstzeit sichtbar bleiben. Ollama oder LM Studio heben diese Grenze im Spiel auf. Die Programme selbst sind kostenlos; der Spielpreis steht für Einrichtung und Betreuung. Der passende Knopf leuchtet gerade rot.",
    sag:"Hier greift eine vereinfachte Hofregel. Mit reinem llama C P P ist pro Bucht und Tag nur ein Modellwechsel vorgesehen, damit Lade- und Rüstzeit sichtbar bleiben. Ollama oder L M Studio heben diese Grenze im Spiel auf. Die Programme selbst sind kostenlos; der Spielpreis steht für Einrichtung und Betreuung. Der passende Knopf leuchtet gerade rot."},
  hilfe_vram:{titel:"Das Modell passt nicht",ziel:null,
    t:"Keine Sorge, zu wenig Grafikspeicher ist ein häufiger Stolperstein. Der Bedarf besteht aus Modellgewichten, Textzwischenspeicher und Laufzeitreserve. Du kannst eine sparsamere Quantisierung wählen, ein kleineres Modell einsetzen oder eine Karte mit mehr Speicher kaufen. Ein Überhang darf in den Arbeitsspeicher ausweichen, macht das Modell aber deutlich langsamer."},
  ort_kompendium:{titel:"Das Kompendium",ziel:null,
    t:"Das Kompendium ist die kleine KI-Schule deines Hofes. Dort findest du Wissenskarten über Trainingsverfahren, Grafikkarten, Energie und viele weitere Themen. Die Karten erklären die wirkliche Technik, unabhängig von den Spielregeln. Du kannst sie jederzeit in Ruhe nachlesen."},
  hilfe_hofsprecher:{titel:"Der Hofsprecher",ziel:null,
    t:"Mit dem Hofsprecher kannst du den Hof in ganzen Sätzen steuern. Das deutsche Wörterbuch arbeitet sofort, exakt und offline. Die Nadel ist ein zusätzliches kleines Modell im Browser und versteht besonders englische Formulierungen. Vor jeder Änderung zeige ich dir eine Vorschau; erst wenn du auf Machen drückst, wird sie ausgeführt. Ohne Schlüssel beantworte ich Fragen außerdem aus dem Hofbuch, mit Live-Zahlen zu Wetter, Kasse und Zetteln oder mit der passenden Regelstelle."},
  wetter_planung:{titel:"Wetter und Tagesplanung",ziel:null,
    t:"Nach jeder Nacht siehst du die Wettervorhersage für den neuen Tag. Sonne und Wolken bestimmen den Solarertrag, die Windstärke bestimmt den Ertrag deiner Windräder. Sturm legt kleine Windräder still, Nebel dämpft die Sonne, ein Hitzetag kostet Kühlung. Das Wetter ist je Hof gewürfelt, die Vorhersage im Spiel aber exakt. Plane große Aufträge und Trainings passend zur verfügbaren Energie. Wenn es regnet, ziehen dieselben Regenwolken sichtbar über die Farm."},
  zettelschmiede:{titel:"Zettelschmiede und Kundschaft",ziel:null,
    t:"Die Zettelschmiede holt Aufträge aus über fünfzig echten Berufen in zwanzig Sektoren, von der Zimmerei über den Imbiss bis zur Kanzlei und Klinik. Sie erfindet Betriebe, Orte und Anliegen aus geprüften Bausteinen; Wendungen stehen sichtbar auf dem Zettel. Anforderungen, Fristen, Chancen und Geld berechnet weiterhin die Simulation, kein Sprachmodell darf diese Zahlen erfinden. Eine Nadel im Stall sortiert den Posteingang vor und hängt einen zusätzlichen passenden Zettel aus. Komplexe Zettel sind Teamarbeit, sensible Zettel verlangen Fachwissen."},
  hofpost:{titel:"Die Hofpost",ziel:null,
    t:"Die Hofpost fasst morgens Wetter, Kundschaft und besondere Chancen zusammen. Feststehende Dinge erscheinen als Nachricht. Unsichere Hinweise sind immer ausdrücklich als Gerücht gekennzeichnet und müssen nicht eintreffen. Auch neue Dorf-Anliegen und anstehende Entscheidungen meldet der Morgenbericht. So kannst du planen, ohne eine Vermutung mit einer festen Regel zu verwechseln."},
  training_analyse:{titel:"Training auswerten",ziel:null,
    t:"Nach jedem Training vergleicht das Zeugnis die Werte vor und nach dem Lauf. Das Netzdiagramm zeigt Zugewinne, Verluste und mögliche Risiken. Darunter findest du den größten Fortschritt und passende nächste Schritte. Alle Werte stammen direkt aus dem abgeschlossenen Training."},
  quest_freiwillig:{titel:"Freiwillige Hofprojekte",ziel:null,
    t:"Hofprojekte sind freiwillige Ziele für eine Spielwoche, die du selbst wählst. Dazu kommen Dorf-Anliegen: Alle fünf Tage schreibt ein Betrieb aus dem Umland einen Bittbrief mit klarem Ziel, Frist und Prämie. Wenn du ein Ziel erreichst, bekommst du Geld und Ruf. Wenn es nicht klappt, entsteht keine Strafe, und du kannst in der nächsten Woche neu wählen."},
  start_tierkarte:{titel:"Deine erste Tierkarte",ziel:"#ada-tierwerte",
    t:"Hier lernst du dein Modell kennen. Das Netzdiagramm und die Balken zeigen Fähigkeiten wie Wissen, Logik, Code, Stil und Werkzeugnutzung. Die Kacheln darunter zeigen Tempo, Tagesleistung, Speicherbedarf und laufende Kosten. Grün und hohe Werte sind hilfreich, aber für einen Auftrag zählen immer dessen konkrete Anforderungen."},
  start_tieraktionen:{titel:"Was du mit dem Modell tun kannst",ziel:"#ada-bucht-zuweisen",
    t:"Unter den Werten findest du die möglichen Aktionen. Du kannst das Modell später trainieren, ausrüsten, auffrischen, quantisieren oder verkaufen. Jetzt ist zuerst die Rechnerbucht wichtig, denn ein Modell auf der Wiese kann nicht arbeiten. Drücke auf Bucht zuweisen; der Knopf leuchtet rot."},
  start_buchtwahl:{titel:"Rechnerbucht und Grafikkarte wählen",ziel:"#ada-buchtliste",
    t:"Jede Bucht gehört zu einer echten Grafikkarte im Rechenhaus. Vergleiche den Speicherbedarf deines Modells mit dem Grafikspeicher der Karte. Ein grüner Eintrag passt vollständig. Bei einer Warnung wird ein Teil in den Arbeitsspeicher ausgelagert und das Modell arbeitet deutlich langsamer."},
  start_bucht_fertig:{titel:"Das Modell ist einsatzbereit",ziel:"jobs",
    t:"Sehr gut, dein Modell ist jetzt auf der ausgewählten Grafikkarte geladen. Damit kann es Aufträge bearbeiten und später auch trainieren. Als Nächstes gehen wir in die Agentenwerkstatt, wo das Modell sein Agenten-Tool bekommt. Der passende Knopf im Dorf leuchtet rot."},
  start_pinnwand:{titel:"Den ersten Auftrag finden",ziel:"#ada-erster-job",
    t:"Auf der Pinnwand siehst du Bezahlung, Arbeitsmenge, Frist und benötigte Fähigkeiten. Für den ersten Auftrag suche ich dir einen grünen Vorschlag aus, den ein geladenes Modell bewältigen kann. Öffne diesen Vorschlag und prüfe trotzdem alle Angaben. Ein hoher Lohn allein macht einen Auftrag noch nicht passend."},
  start_eignung:{titel:"Ist dein Modell geeignet?",ziel:"#ada-eignung",
    t:"Hier wird jede Anforderung direkt mit den aktuellen Modellwerten verglichen. Grün bedeutet erfüllt; rote Zeilen nennen genau, was fehlt. Bei Zetteln aus Praxis, Kanzlei oder Steuerbüro stehen hier auch das nötige Fachwissen und das Datenschutz-Risiko. Achte zusätzlich auf Qualitätschance, benötigte Stunden und Lieferfrist. Teile erst ein Modell ein, wenn alle Stufen grün sind und genug Zeit bleibt."},
  start_zusage:{titel:"Die Zusage noch einmal prüfen",ziel:"#ada-zusage",
    t:"Dein Modell ist jetzt eingeteilt. In der Zusammenfassung stehen Qualitätschance, geschätzte Arbeitszeit und das verfügbare Fristbudget. Grün bedeutet Reserve, Gelb ist knapp und Rot warnt vor einem wahrscheinlichen Fristbruch. Bei komplexen Zetteln wählst du oben die Teamgröße, und die Tabelle zeigt die Dauer je Anzahl der Agenten. Wenn alles passt, drücke auf Verbindlich übernehmen."},
  start_auftrag_laeuft:{titel:"Der erste Auftrag läuft",ziel:"#ada-erster-lauf",
    t:"Geschafft, dein erster Auftrag läuft! Das Modell bleibt während der Arbeit belegt, und der Fortschrittsbalken zeigt die erledigte Arbeitsmenge. Ist es schnell genug, kann der Auftrag noch heute fertig werden; sonst arbeitet es am nächsten Hoftag weiter. Bei der Abnahme erhältst du Geld, Erfahrung und eine Kundenbewertung."},
  start_geschirr:{titel:"Vom Modell zum Agenten: das Agenten-Tool",ziel:"geschirr",
    t:"Sehr gut, dein Modell ist geladen. Bevor wir zur Pinnwand gehen, kommt ein Schritt, der später über die besten Aufträge entscheidet: die Agentenwerkstatt. Ein Agenten-Tool ist die Arbeitsumgebung eines Modells. Es gibt ihm Werkzeuge, ein festes Ausgabeformat und mehrere Handlungsschritte. Erst damit wird aus einem Modell ein Agent, der E-Mails ablegt, Formulare ausfüllt oder Tickets löst. Das Basis-Tool funktioniert mit jedem Modell und kostet nichts. Die Eignungsmatrix zeigt in Grün, welche Kombination gut funktioniert. Wähle nach Zweck: für Code ein Coding-Tool, für Büro und Support ein leichtes Tool. Zettel mit Patientendaten, Akten oder Personalunterlagen verlangen Fachwissen aus Kursen. Ein Agenten-Tool mit Schutzfunktionen ersetzt dieses Fachwissen nicht, halbiert aber das verbleibende Datenschutz-Risiko. Der Knopf zur Agentenwerkstatt leuchtet rot."},
  start_geschirr_fertig:{titel:"Dein Modell ist ein Agent",ziel:"jobs",
    t:"Prima, dein Modell verwendet jetzt ein Agenten-Tool und darf Agenten-Zettel annehmen. Merke dir: Mehrere Agenten mit demselben Tool arbeiten als eingespieltes Team. Bei komplexen Aufträgen zeigt die Pinnwand, wie viele Tage ein, zwei oder drei Agenten brauchen. Jetzt zur Pinnwand, der Knopf leuchtet rot."},
  team_agenten:{titel:"Agenten-Teams",ziel:null,
    t:"Komplexe Zettel tragen den Chip Team bis zwei, drei oder vier. Dort dürfen mehrere Agenten gleichzeitig arbeiten. Die Arbeit teilt sich, aber Abstimmung kostet: je weiterem Agenten zehn Prozent mehr Arbeit, mit demselben Tool nur fünf. Aus vier Tagen werden so mit zwei Agenten gut zwei Tage, mit dreien gut anderthalb. Die Zettelkarte rechnet das mit deinen schnellsten freien Agenten vor. Die Teamgröße wählst du oben auf dem Einsatzblatt."},
  datenschutz:{titel:"Datenschutz auf dem Hof",ziel:null,
    t:"Zettel aus Medizin, Recht, Steuern, Personal und Pflege enthalten Daten echter Menschen. Wer sie mit ungeschulten Modellen oder über Leih-Tiere in der Cloud bearbeitet, riskiert einen Verstoß mit Strafe, Rufverlust und einer Abmahnung der Aufsicht. Im normalen Hofalltag und im Marktbetrieb wird der Hof nach der zweiten Abmahnung geschlossen, im behüteten Spiel nach der dritten. Schutz beginnt mit echter Ausbildung: In der Agentenwerkstatt buchst du Kurse je Fachgebiet, vom Grundkurs bis zum Fachzertifikat. Agenten-Tools mit Rechtebegrenzung sowie die Forschung „Schutzregeln“ senken das verbleibende Risiko, ersetzen das verlangte Fachwissen aber nicht. Erst neunzig Punkte Fachwissen im Datenschutz beseitigen das Verstoßrisiko vollständig. Diese Zettel zahlen deutlich mehr, sodass sich Kurse nach wenigen Aufträgen rechnen."},
  abmahnung:{titel:"Abmahnung der Aufsicht",ziel:"geschirr",
    t:"Das war ein Datenschutz-Verstoß. Die Aufsicht hat eine Abmahnung ausgesprochen. Im normalen Hofalltag und im Marktbetrieb schließen zwei Abmahnungen den Hof, im behüteten Spiel drei. Was jetzt hilft: Schule die Modelle, die Akten oder Befunde bearbeiten, in der Agentenwerkstatt im Fachgebiet Datenschutz. Weise ihnen ein Agenten-Tool mit Schutzfunktionen zu und setze für solche Zettel keine Leih-Tiere ein. Das Tool halbiert nur das verbleibende Risiko; vollständig verschwindet es erst ab neunzig Punkten Fachwissen im Datenschutz. Die Agentenwerkstatt leuchtet rot."},
  tagesplanung:{titel:"Die Tagesplanung",ziel:null,
    t:"Nach jeder Nacht beginnt der Tag mit der Tagesplanung. Oben stehen das Wetter von heute und morgen mit Solar- und Windfaktor, darunter die erwartete Energie aus Sonne und Wind, dein Bedarf für Tag und Nacht, der Netzbezug in Kilowattstunden und Euro und der Akkustand. Dann folgen offene Entscheidungen, Dorf-Anliegen und die Zahl der offenen Zettel. Von hier springst du zur Pinnwand, zur Energieplanung oder ins Rechenhaus."},
  ereignis_entscheidung:{titel:"Ereignisse mit Entscheidung",ziel:null,
    t:"Manche Ereignisse stellen dich vor eine Wahl, etwa wenn die Kühlung leckt oder das Dorfradio ein Interview will. Jede Option nennt vorher ihre Zahlen: Geld, Ruf, Erfahrung, Daten oder eine Folgewirkung mit Dauer. Du entscheidest im Morgenbericht oder im Hofhaus. Wer bis zum Tagesende nicht entscheidet, bekommt die Standard-Option. Es gibt keine versteckten Würfel: Was auf der Karte steht, passiert."},
  anliegen:{titel:"Dorf-Anliegen",ziel:null,
    t:"Ab dem dritten Hoftag schreibt alle fünf Tage ein Betrieb aus dem Umland einen Bittbrief: zum Beispiel drei saubere Textzettel, zwei Nächte mit Zusatzarbeit oder eine bestimmte Menge Eigenenergie. Jedes Anliegen hat sechs Tage Frist und eine Prämie mit Ruf. Höchstens zwei sind gleichzeitig offen, und nichts davon ist Pflicht: Ein verfallenes Anliegen kostet nichts."},
  fachbildung:{titel:"Fachbildung",ziel:null,
    t:"Fachwissen misst je Gebiet von null bis hundert, wie erfahren ein Modell in Datenschutz, Medizin, Recht, Steuern, Personal oder Versicherung ist. Kurse in der Agentenwerkstatt sind Trainingsläufe: Der Grundkurs dauert einen Tag, der Aufbaukurs zwei, das Fachzertifikat drei. Jeder Kurs kostet Geld und kuratierte Daten, größere Modelle zahlen mehr, und das Modell fällt solange aus. Mit erforschten Verfahren wählst du die Technik: SFT lernt gründlicher, LoRA ist schneller und QLoRA billiger. DPO ist nur für Datenschutz-Kurse wählbar und erhöht dort den Wissensgewinn; allein ist es kein Schutz. Saubere Zettel im Gebiet bringen Praxis dazu. Die Zettel verlangen ein Mindest-Fachwissen, das mit den Hoftagen steigt, und zahlen dafür deutlich mehr."},
  nadel:{titel:"Die Nadel",ziel:null,
    t:"Die Nadel ist ein echtes Modell namens Needle zwei: fünfundvierzig Millionen Parameter in vierzehn Megabyte, achtundzwanzig Megabyte Arbeitsspeicher, ein Fenster von zweihundertsechsundfünfzig Token. Sie kann genau eines: aus Text einen Werkzeugaufruf oder ein Datenfeld machen. Sie schreibt keine Texte, weiß nichts und versteht Englisch besser als Deutsch. Auf dem Hof sortiert sie Mikro-Zettel und den Posteingang, läuft auf einem Raspberry Pi für hundertzwanzig Euro und steuert als Hofsprecher deinen Hof in ganzen Sätzen. Alle Zahlen stammen von der Modellkarte des Herstellers."},
  hof_geschlossen:{titel:"Der Hof ist geschlossen",ziel:null,
    t:"Die Datenschutzaufsicht hat deinem Hof nach der letzten Abmahnung die Betriebserlaubnis entzogen. Das ist hart, aber im echten Leben endet so mancher kleine Dienstleister. Die Lehre: Wer Daten echter Menschen verarbeitet, braucht geschulte Modelle, Agenten-Tools mit Sandbox, Rechtebegrenzung und Prüfprotokoll, keine Leih-Tiere für Akten und Befunde sowie klare Schutzregeln. Hier oder im Hofhaus kannst du neu anfangen, und diesmal weißt du, worauf es ankommt."},
  meisterbrief:{titel:"Der Hofmeisterbrief",ziel:"#tagknopf",
    t:"Der Hof hat ein Ziel, und dorthin führen fünf Wege: eine Zuchtlinie über drei Generationen, ein Rechenpark mit eigenem Strom, ein vollständig ausgebauter Forschungsbaum, ein Handelshaus mit hundert sauberen Aufträgen oder ein Fachhaus mit drei Zertifikaten und keiner einzigen Abmahnung. Zwei davon und Hofstufe zehn bringen dir den Hofmeisterbrief. Alle fünf und Hofstufe zwölf machen dich zur Legende. Gespielt wird danach weiter – der Brief hängt im Hofhaus, und die Ehre bleibt."},
  mcp_werkstatt:{titel:"Die MCP-Werkstatt",ziel:null,
    t:"Ein Agent ist nur so gut wie seine Anschlüsse. Das Model Context Protocol ist der offene Standard dafür: Dein Agenten-Tool ist der Host, jeder Dienst ein Server mit Werkzeugen, Datenquellen und Vorlagen. In der MCP-Werkstatt schließt du sie Knoten für Knoten an – die Leitung zuerst, dann Datei, Post, Buchhaltung und Netz. Und vergiss die Sicherheit nicht: Eine vergiftete Werkzeugbeschreibung ist Text, den dein Modell liest. Freigabeliste, Sandkasten und Prüfprotokoll halten den Schaden klein."},
  hofuhr:{titel:"Die Hofuhr und das Warten",ziel:null,
    t:"Die Hofuhr läuft von sechs bis zweiundzwanzig Uhr. Ein Zettel bindet ein Modell nur so lange, wie seine Arbeit dauert: Ist ein Auftrag nach vier Stunden fertig, wird er sofort abgenommen und bezahlt, und das Modell ist wieder frei für den nächsten Zettel. Mit dem Warten-Knopf in der Hofleiste spulst du eine Stunde, bis zur nächsten Abnahme oder bis Feierabend vor. Wer den Tag früh beendet, lässt laufende Aufträge weiterarbeiten, aber freie Modelle stehen bis morgen still, und die Dorfplatz-Spiele des Tages verfallen. Die Nachtplanung zeigt dir vorher, wie viel dadurch liegen bleibt."}
};
